<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import type {Api} from './api'
const props=defineProps<{api:Api}>()
const kind=ref('audit'),action=ref(''),state=ref(''),page=ref(1),total=ref(0),items=ref<Record<string,unknown>[]>([])
let requestSerial=0
async function load(){const request=++requestSerial;try{const data=await props.api<{items:Record<string,unknown>[];total:number}>(`/admin/logs/${kind.value}?offset=${(page.value-1)*20}&limit=20&action=${encodeURIComponent(action.value)}&state=${encodeURIComponent(state.value)}`);if(request!==requestSerial)return;items.value=data.items;total.value=data.total}catch(e){if(request===requestSerial)ElMessage.error((e as Error).message)}}
onMounted(load)
</script>
<template><h1>操作审计与 AI 调用记录</h1><p>查看动作、对象、时间、状态及安全错误摘要。调用成功表示接口返回，业务完成状态请查看对应任务。</p><el-radio-group v-model="kind" @change="page=1;load()"><el-radio-button value="audit">操作审计</el-radio-button><el-radio-button value="ai">AI 调用记录</el-radio-button></el-radio-group><el-form inline @submit.prevent="page=1;load()"><el-form-item :label="kind==='audit'?'操作动作':'调用类型'"><el-input v-model="action" placeholder="按名称包含" clearable/></el-form-item><el-form-item label="执行状态"><el-select v-model="state" clearable placeholder="全部状态" style="width:180px"><el-option v-for="(label,value) in {success:'成功',succeeded:'已完成',failed:'失败',denied:'已拒绝'}" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-button native-type="submit">查询</el-button></el-form><el-table :data="items"><el-table-column v-if="kind==='audit'" prop="action" label="动作"/><el-table-column v-else prop="operation" label="调用类型"/><el-table-column prop="target_id" label="对象/任务编号"/><el-table-column :prop="kind==='ai'?'state':'outcome'" label="状态"/><template v-if="kind==='ai'"><el-table-column prop="model" label="模型"/><el-table-column prop="elapsed_ms" label="耗时ms"/><el-table-column prop="error_code" label="错误码"/></template><el-table-column v-else prop="request_id" label="追踪编号"/><el-table-column label="时间"><template #default="s">{{new Date(s.row.created_at*1000).toLocaleString()}}</template></el-table-column></el-table><el-empty v-if="!items.length" description="当前条件下暂无记录，可调整筛选条件" :image-size="48"/><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></template>
